/**
 * Date policy
 * - taskDate is a calendar date (no time). It is accepted as "YYYY-MM-DD" and
 *   stored as UTC midnight, so it never shifts between time zones. Clients
 *   should read it back with `value.slice(0, 10)` or format it in UTC.
 * - createdAt / updatedAt are real instants generated by the server.
 * - "Today" for dashboard statistics is computed in the business time zone
 *   (APP_TIMEZONE), not the server's or the browser's local zone.
 */

const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})(?:$|T)/;

/** Parses "YYYY-MM-DD" (an ISO timestamp is truncated to its date part). Returns null if invalid. */
export function parseCalendarDate(value) {
  if (typeof value !== 'string') return null;
  const match = CALENDAR_DATE.exec(value.trim());
  if (!match) return null;

  const [year, month, day] = match.slice(1).map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  // Rejects impossible dates such as 2026-02-30 that Date would roll over.
  if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) {
    return null;
  }
  return date;
}

export function isValidTimeZone(timeZone) {
  try {
    new Intl.DateTimeFormat('en-US', { timeZone });
    return true;
  } catch {
    return false;
  }
}

/** The wall-clock time in `timeZone` at `date`, expressed as if it were UTC (ms). */
function wallClockAsUtc(date, timeZone) {
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat('en-US', {
      timeZone,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    })
      .formatToParts(date)
      .map((part) => [part.type, part.value])
  );
  return Date.UTC(+parts.year, +parts.month - 1, +parts.day, +parts.hour, +parts.minute, +parts.second);
}

/** The UTC instant of midnight at the start of `now`'s day in `timeZone` (DST-safe). */
export function startOfDayInTimeZone(now, timeZone) {
  const nowMs = Math.floor(now.getTime() / 1000) * 1000;
  const wall = new Date(wallClockAsUtc(new Date(nowMs), timeZone));
  const midnightWall = Date.UTC(wall.getUTCFullYear(), wall.getUTCMonth(), wall.getUTCDate());

  // First guess uses the current offset; the second pass corrects for a DST
  // change between midnight and now.
  let guess = midnightWall - (wall.getTime() - nowMs);
  const offsetAtGuess = wallClockAsUtc(new Date(guess), timeZone) - guess;
  guess = midnightWall - offsetAtGuess;
  return new Date(guess);
}
